mapper.update:
update safety_goods_out_process
set
    cur_node_id=#{curNodeId},
    cur_node_name = #{curNodeName}

    ,cur_node_handler = #{curDealHandler}


    ,cur_handler_name = #{curHandlerName}


  ,status = #{fdStatus}


  ,node_flag = #{nodeFlag}


  ,release_status = #{releaseStatus}

where id = #{id}

update safety_goods_out_process
set flow_id = #{flowId}
where id = #{id}

mapper.select:
select 
from safety_goods_out_process p
     left join safety_goods_out_process_ext pe on p.id = pe.relation_id
where 1 = 1


  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select outside_name,outside_phone,goout_phone,goout_emp_no,
                goout_emp_dept,goout_emp_name,delivery_unit_name,is_vehicle,vehicle_no,max(create_time) as createTime
  from safety_goods_out_process
 where (submit_phone = #{submitNo} or submit_no =  #{submitNo})

  and status = #{status}

group by outside_name,outside_phone,goout_phone,goout_emp_no,goout_emp_dept,goout_emp_name,delivery_unit_name,is_vehicle,vehicle_no order by createTime DESC


    limit ${offset}, ${limit}


    limit ${limit}

select count(1) from ( select outside_name,outside_phone,goout_phone,goout_emp_no,goout_emp_dept,goout_emp_name,delivery_unit_name from safety_goods_out_process where (submit_phone = #{submitNo} or submit_no = #{submitNo})
and status = #{status}
group by outside_name,outside_phone,goout_phone,goout_emp_no,goout_emp_dept,goout_emp_name,delivery_unit_name,is_vehicle,vehicle_no ) as p_limit

if.foreach:
update safety_goods_out_process
set status = #{lis.status},
is_time_out = #{lis.isTimeOut}
where id = #{lis.id}

mapper.select:
select
    id,cur_node_handler,cur_handler_name,cur_node_id,cur_node_name
from safety_goods_out_process
where status = #{status}

  and create_time < #{beginDate}

select
  r.process_id,r.receive_emp_no,r.receive_emp_eip,r.receive_emp
from safety_goods_out_process p
left join safety_goods_out_detail_receive r on r.process_id = p.id
where p.status = #{status}

    and p.publish_time < now()

and p.cur_node_id = #{curNodeId}

  and r.receive_status is null
  or r.receive_status = 0


  and p.is_set_accept = #{isSetAccept}

mapper.delete:
delete from safety_goods_out_auth
where emp_no in
(
    select EMPLOYEE_CODE from safety_depart_change_list
                         where UPDATE_TIME >= #{beginTime}

                           and UPDATE_TIME <= #{endTime}

  )
